/* Rutta Sidefit viewer. Geometry comes from the shared v5 product model. */
(() => {
  "use strict";
  const model = {"black":["","",2820],"stainless":["","",24480],"body":["","",8154],"gasket":["","",7344],"contact":["","",176256],"switchgrip":["","",22032],"switchgripwall":["","",3672],"recess":["","",7344],"led":["","",7344],"etch":["","",381],"amber":["","",7344],"switch":["","",7968],"liner":["","",4488],"track":["","",7344],"shell":["","",5712]};
  const finishRgb = {"silver":[0.865,0.87,0.875],"sky":[0.595,0.715,0.825],"starlight":[0.85,0.76,0.585],"midnight":[0.125,0.165,0.222]};
  const finishHex = Object.freeze({"silver":"#c7c9ca","sky":"#aec3d7","starlight":"#d6c9ad","midnight":"#374454"});
  const positions = {
    home: [-0.27, 0.48],
    front: [-0.05, 0.32],
    back: [Math.PI - 0.44, 0.50],
    top: [-0.24, 1.48],
    bottom: [Math.PI - 0.88, -1.14],
  };
  const materials = {
    etch: [[0.6, 0.6, 0.6], 0.82, 0.28],
    body: [[0.72, 0.74, 0.75], 0.85, 0.22],
    shell: [[0.78, 0.795, 0.81], 0.97, 0.13],
    stainless: [[0.70, 0.72, 0.74], 0.92, 0.17],
    switch: [[0.66, 0.68, 0.70], 0.90, 0.20],
    switchgrip: [[0.34, 0.37, 0.39], 0.45, 0.29],
    switchgripwall: [[0.48, 0.51, 0.53], 0.79, 0.28],
    led: [[0.18, 0.23, 0.20], 0.12, 0.40],
    track: [[0.13, 0.15, 0.17], 0.18, 0.48],
    gasket: [[0.075, 0.08, 0.085], 0.06, 0.52],
    black: [[0.022, 0.024, 0.027], 0.07, 0.58],
    liner: [[0.74, 0.755, 0.77], 0.015, 0.18],
    recess: [[0.024, 0.027, 0.031], 0.04, 0.58],
    contact: [[0.74, 0.60, 0.38], 0.95, 0.19],
    amber: [[0.95, 0.45, 0.08], 0.07, 0.34],
  };

  const objectVertex = `
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    uniform vec3 uRight, uUp, uToward, uCenter, uShift;
    uniform vec2 uScale;
    varying vec3 vPos, vNormal;
    void main() {
      vPos = aPosition / 1000.0 + uShift;
      vNormal = aNormal;
      vec3 p = vPos - uCenter;
      gl_Position = vec4(dot(p, uRight) * uScale.x, dot(p, uUp) * uScale.y, -dot(p, uToward) / 34.0, 1.0);
    }
  `;

  const objectFragment = `
    precision highp float;
    varying vec3 vPos, vNormal;
    uniform vec3 uAlbedo, uToward;
    uniform float uMetallic, uRoughness, uLight, uDisplayStudio;
    uniform vec3 uLightColor;
    const vec3 key = vec3(-0.43, -0.27, 0.86);
    const vec3 strip = vec3(0.62, 0.09, 0.78);
    const vec3 fill = vec3(-0.78, 0.35, 0.51);
    const vec3 endLight = vec3(0.06, -0.99, 0.12);
    float saturate(float x) {return clamp(x, 0.0, 1.0);}
    vec3 studio(vec3 r, float rough) {
      float keyLight = pow(saturate(dot(r, key)), mix(28.0, 5.0, rough));
      float rimLight = pow(saturate(dot(r, strip)), mix(66.0, 9.0, rough));
      float fillLight = pow(saturate(dot(r, fill)), mix(24.0, 4.0, rough));
      float edgeLight = pow(saturate(dot(r, endLight)), mix(30.0, 7.0, rough));
      float horizon = smoothstep(-0.18, 0.75, r.z);
      return mix(vec3(0.32, 0.34, 0.35), vec3(0.65, 0.67, 0.69), horizon)
        + vec3(1.17, 1.14, 1.09) * keyLight
        + vec3(0.84, 0.91, 1.03) * rimLight
        + vec3(0.43, 0.48, 0.55) * fillLight
        + vec3(0.61, 0.62, 0.65) * edgeLight;
    }
    void main() {
      vec3 n = normalize(vNormal);
      vec3 r = reflect(-uToward, n);
      float f = pow(1.0 - saturate(dot(n, uToward)), 5.0);
      float hemi = n.z * 0.5 + 0.5;
      float diffuseLight = 0.36 + 0.52 * hemi + 0.30 * saturate(dot(n, key));
      // The edge closest to the stage and the plug recess receive less bounce.
      float bounce = mix(0.73, 1.0, smoothstep(-2.70, 0.9, vPos.z));
      float insidePlug = step(0.32, vPos.x) * (1.0 - smoothstep(0.80, 1.25, abs(vPos.z)));
      bounce *= mix(1.0, 0.7, insidePlug);
      vec3 base = uAlbedo * uAlbedo;
      vec3 specular = studio(r, uRoughness) * mix(vec3(0.047 + 0.11 * f), base + 0.27 * f, uMetallic);
      vec3 color = (diffuseLight * base * (1.0 - uMetallic) + specular) * bounce;
      if (uDisplayStudio > 0.5 && uMetallic > 0.7) {
        // Finite strip lights give even a broad, flat aluminum face a reflected gradient.
        float card = 0.5 + 0.5 * cos(3.1 * r.z + vPos.y * 0.115 - 0.6);
        float ribbon = exp(-pow((r.z - 0.35 + vPos.y * 0.015) * 3.2, 2.0));
        color = color * (0.82 + 0.32 * card) + base *
          (0.17 + 0.35 * card + 0.33 * ribbon + 0.09 * hemi);
      }
      vec3 emission = uLightColor * uLight;
      color = color + emission;
      color = 1.15 * color / (1.0 + 0.32 * color);
      color = pow(clamp(color, 0.0, 1.0), vec3(0.4545));
      gl_FragColor = vec4(color, 1.0);
    }
  `;

  const stageVertex = `
    attribute vec2 aPosition;
    varying vec2 vUV;
    void main() {
      vUV = aPosition;
      gl_Position = vec4(aPosition, 0.99, 1.0);
    }
  `;

  const stageFragment = `
    precision mediump float;
    varying vec2 vUV;
    uniform vec2 uShadowAt, uShadowAxis, uShadowSize;
    uniform float uAspect;
    void main() {
      vec2 aspect = vec2(uAspect,1.0);
      vec2 d = (vUV - uShadowAt) * aspect;
      vec2 perp = vec2(-uShadowAxis.y, uShadowAxis.x);
      float along = dot(d,uShadowAxis);
      float across = dot(d,perp);
      float halfLine = max(0., uShadowSize.x - 0.070);
      vec2 centerDist = vec2(max(0.,abs(along)-halfLine), across);
      float wide = exp(-dot(d,d)*6.5);
      vec2 q = centerDist / max(vec2(0.04), vec2(uShadowSize.y * 0.80, uShadowSize.y));
      float shadow = exp(-dot(q,q)*1.56) * 0.16 + 0.034 * wide;
      float falloff = smoothstep(0.1, 1.6, length(vec2(vUV.x*0.75,vUV.y*0.9) - vec2(0.12,0.39)));
      vec3 color = vec3(0.943,0.951,0.956) - vec3(0.110,0.105,0.096) * falloff - shadow;
      gl_FragColor = vec4(color,1.0);
    }
  `;

  function compile(gl, vertexSource, fragmentSource) {
    function shader(type, source) {
      const item = gl.createShader(type);
      gl.shaderSource(item, source);
      gl.compileShader(item);
      if (!gl.getShaderParameter(item, gl.COMPILE_STATUS)) {
        const log = gl.getShaderInfoLog(item);
        gl.deleteShader(item);
        throw new Error("Rutta 3D shader: " + log);
      }
      return item;
    }
    const vertex = shader(gl.VERTEX_SHADER, vertexSource);
    const fragment = shader(gl.FRAGMENT_SHADER, fragmentSource);
    const program = gl.createProgram();
    gl.attachShader(program, vertex);
    gl.attachShader(program, fragment);
    gl.linkProgram(program);
    gl.deleteShader(vertex);
    gl.deleteShader(fragment);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
      const log = gl.getProgramInfoLog(program);
      gl.deleteProgram(program);
      throw new Error("Rutta 3D program: " + log);
    }
    const attrib = name => gl.getAttribLocation(program, name);
    const uniform = name => gl.getUniformLocation(program, name);
    return { program, attrib, uniform };
  }

  function mount(canvas, { transparent = false, inline = false } = {}) {
    const gl = canvas.getContext("webgl", { alpha: transparent, antialias: true, powerPreference: "high-performance" });
    if (!gl) throw new Error("The browser could not open a WebGL context for Rutta.");
    const stage = compile(gl, stageVertex, stageFragment);
    const object = compile(gl, objectVertex, objectFragment);
    const bytes = encoded => Uint8Array.from(atob(encoded), char => char.charCodeAt(0));
    function buffer(target, values) {
      const id = gl.createBuffer();
      gl.bindBuffer(target, id);
      gl.bufferData(target, values, gl.STATIC_DRAW);
      return id;
    }
    const backdrop = buffer(gl.ARRAY_BUFFER, new Float32Array([-1,-1, 1,-1, -1,1, 1,1]));
    const parts = Object.entries(model).map(([name, [vertices, faces, count]]) => ({
      name,
      vertices: buffer(gl.ARRAY_BUFFER, bytes(vertices)),
      indices: buffer(gl.ELEMENT_ARRAY_BUFFER, bytes(faces)),
      count,
    }));
    const projection = Object.fromEntries([
      "Right", "Up", "Toward", "Center", "Scale", "Shift", "Albedo", "Metallic", "Roughness", "Light", "LightColor", "DisplayStudio",
    ].map(name => [name, object.uniform("u" + name)]));
    const studio = Object.fromEntries([
      "ShadowAt", "ShadowAxis", "ShadowSize", "Aspect",
    ].map(name => [name, stage.uniform("u" + name)]));
    const attr = { stage: stage.attrib("aPosition"), position: object.attrib("aPosition"), normal: object.attrib("aNormal") };
    const homeCenter = [-0.45, 16.1, 0.12];
    const center = [...homeCenter];
    let centerGoal = homeCenter;
    const motion = matchMedia("(prefers-reduced-motion: reduce)");
    let azimuth = positions.home[0], elevation = positions.home[1], scale = 1;
    let azGoal = azimuth, elGoal = elevation, scaleGoal = 1;
    let shift = 0, muted = false, powered = false, voice = false, finish = "silver";
    let disposed = false, failed = false, pending = 0;
    const pointers = new Map();
    const cleanups = [];
    const previousTouch = canvas.style.touchAction;
    canvas.style.touchAction = inline ? "pan-y" : "none";

    function clamp(value, low, high) { return Math.max(low, Math.min(high, value)); }
    function on(target, type, callback, options) {
      target.addEventListener(type, callback, options);
      cleanups.push(() => target.removeEventListener(type, callback, options));
    }
    function schedule() {
      if (!disposed && !failed && !pending) pending = requestAnimationFrame(draw);
    }
    function dot(a, b) { return a[0]*b[0] + a[1]*b[1] + a[2]*b[2]; }
    function draw(time) {
      pending = 0;
      if (disposed || failed) return;
      const ratio = Math.min(2, window.devicePixelRatio || 1);
      const width = Math.round(canvas.clientWidth * ratio);
      const height = Math.round(canvas.clientHeight * ratio);
      if (!width || !height) return;
      if (canvas.width !== width || canvas.height !== height) {
        canvas.width = width;
        canvas.height = height;
      }
      const ease = motion.matches ? 1 : 0.22;
      azimuth += (azGoal - azimuth) * ease;
      elevation += (elGoal - elevation) * ease;
      scale += (scaleGoal - scale) * ease;
      for (let i = 0; i < 3; i++) center[i] += (centerGoal[i] - center[i]) * ease;
      const shiftGoal = muted ? 1.28 : 0;
      shift += (shiftGoal - shift) * ease;
      const a = azimuth;
      const e = elevation;
      const right = [-Math.sin(a), -Math.cos(a), 0];
      const up = [Math.cos(a)*Math.sin(e), -Math.sin(a)*Math.sin(e), Math.cos(e)];
      const toward = [-Math.cos(a)*Math.cos(e), Math.sin(a)*Math.cos(e), Math.sin(e)];
      const aspect = width / height;
      const xScale = scale / Math.max(20.8, aspect * 11.4);
      const yScale = xScale * aspect;
      const lightOn = powered && !muted;
      const breath = !lightOn ? 0 : voice ? 1.0 : motion.matches ? 0.85 : 0.48 + 0.58 * (0.5 - 0.5 * Math.cos(time * 0.0015708));
      const lightColor = voice ? [1.0, 0.54, 0.10] : [0.55, 0.94, 0.69];

      gl.viewport(0, 0, width, height);
      gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
      if (!transparent) {
        gl.disable(gl.DEPTH_TEST);
        gl.useProgram(stage.program);
        gl.bindBuffer(gl.ARRAY_BUFFER, backdrop);
        gl.enableVertexAttribArray(attr.stage);
        gl.vertexAttribPointer(attr.stage, 2, gl.FLOAT, false, 0, 0);
        const floor = [-2.80 - center[0], 16.0 - center[1], -3.14 - center[2]];
        const along = [right[1], up[1]];
        const alongLength = Math.max(0.001, Math.hypot(along[0], along[1]));
        gl.uniform2f(studio.ShadowAt, dot(floor, right) * xScale + 0.027, dot(floor,up) * yScale - 0.022);
        gl.uniform2f(studio.ShadowAxis, along[0] / alongLength, along[1] / alongLength);
        gl.uniform2f(studio.ShadowSize, 15.8 * yScale * alongLength, (2.5 + 1.2*Math.max(0,Math.sin(e))) * yScale);
        gl.uniform1f(studio.Aspect, aspect);
        gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
        gl.disableVertexAttribArray(attr.stage);
      }

      gl.enable(gl.DEPTH_TEST);
      gl.useProgram(object.program);
      gl.uniform1f(projection.DisplayStudio, transparent ? 1.0 : 0.0);
      gl.uniform3fv(projection.Right, right);
      gl.uniform3fv(projection.Up, up);
      gl.uniform3fv(projection.Toward, toward);
      gl.uniform3fv(projection.Center, center);
      gl.uniform2f(projection.Scale, xScale, yScale);
      gl.enableVertexAttribArray(attr.position);
      gl.enableVertexAttribArray(attr.normal);
      for (const part of parts) {
        const [base, metal, roughness] = materials[part.name];
        const cap = part.name === "switch";
        const movesWithCap = cap || part.name.startsWith("switchgrip");
        const travel = movesWithCap ? shift : 0;
        const tint = finishRgb[finish];
        const albedo = part.name === "etch" ? tint.map(c => c * (finish === "midnight" ? 1.20 : 0.81)) : part.name === "body" ? tint : cap && finish !== "silver" ? tint.map(c => c * 0.92) : base;
        gl.uniform3f(projection.Shift, 0, travel, 0);
        gl.uniform3fv(projection.Albedo, albedo);
        gl.uniform1f(projection.Metallic, metal);
        gl.uniform1f(projection.Roughness, roughness);
        gl.uniform1f(projection.Light, part.name === "led" ? breath : 0);
        gl.uniform3f(projection.LightColor, lightColor[0], lightColor[1], lightColor[2]);
        gl.bindBuffer(gl.ARRAY_BUFFER, part.vertices);
        gl.vertexAttribPointer(attr.position, 3, gl.SHORT, false, 10, 0);
        gl.vertexAttribPointer(attr.normal, 3, gl.BYTE, true, 10, 6);
        gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, part.indices);
        gl.drawElements(gl.TRIANGLES, part.count, gl.UNSIGNED_SHORT, 0);
      }
      gl.disableVertexAttribArray(attr.position);
      gl.disableVertexAttribArray(attr.normal);
      const settles = Math.abs(azGoal-azimuth) + Math.abs(elGoal-elevation) + Math.abs(scaleGoal-scale) + Math.abs(shiftGoal-shift);
      const centerTravel = Math.max(...center.map((v, i) => Math.abs(v - centerGoal[i])));
      if (centerTravel > 0.001 || settles > 0.0008 || (lightOn && !voice && !motion.matches && toward[2] > 0.015)) schedule();
    }

    function setView(name) {
      const view = Object.hasOwn(positions, name) ? positions[name] : null;
      if (!view) return;
      azGoal = azimuth + Math.atan2(Math.sin(view[0]-azimuth), Math.cos(view[0]-azimuth));
      elGoal = view[1];
      schedule();
    }
    function setCamera({ angle, pitch, magnification, target }) {
      azGoal = azimuth + Math.atan2(Math.sin(angle - azimuth), Math.cos(angle - azimuth));
      elGoal = clamp(pitch, -1.34, 1.562);
      scaleGoal = clamp(magnification, 0.60, 2.65);
      centerGoal = target;
      schedule();
    }
    function setMuted(value) {
      muted = Boolean(value);
      powered = true;
      schedule();
    }
    function setPowered(value) {
      powered = Boolean(value);
      if (!powered) voice = false;
      schedule();
    }
    function setActivity(value) {
      voice = Boolean(value);
      powered = true;
      muted = false;
      schedule();
    }
    function setFinish(next) {
      if (!Object.hasOwn(finishRgb,next)) return;
      finish = next;
      schedule();
    }
    function zoom(factor) {
      if (!(factor > 0) || !Number.isFinite(factor)) return;
      scaleGoal = clamp(scaleGoal * factor, 0.60, 2.65);
      schedule();
    }
    function orbit(dx, dy) {
      azGoal += dx * 0.009;
      elGoal = clamp(elGoal + dy * 0.0075, -1.34, 1.562);
      schedule();
    }
    function reset() {
      scaleGoal = 1;
      centerGoal = homeCenter;
      setView("home");
    }
    function pinchDistance() {
      const [a, b] = pointers.values();
      return Math.max(4, Math.hypot(a.x-b.x, a.y-b.y));
    }
    on(canvas, "pointerdown", event => {
      if (event.pointerType === "mouse" && event.button !== 0) return;
      canvas.setPointerCapture(event.pointerId);
      pointers.set(event.pointerId, {x:event.clientX,y:event.clientY});
      canvas.style.cursor = "grabbing";
    });
    on(canvas, "pointermove", event => {
      const previous = pointers.get(event.pointerId);
      if (!previous) return;
      const oldDist = pointers.size > 1 ? pinchDistance() : 0;
      pointers.set(event.pointerId, {x:event.clientX,y:event.clientY});
      if (oldDist) zoom(pinchDistance() / oldDist);
      else orbit(event.clientX - previous.x, event.clientY - previous.y);
    });
    const release = event => {
      pointers.delete(event.pointerId);
      if (!pointers.size) canvas.style.cursor = "grab";
    };
    ["pointerup", "pointercancel", "lostpointercapture"].forEach(name => on(canvas, name, release));
    on(canvas, "wheel", event => {
      if (inline) return; // Let the document scroll through an embedded model.
      if (event.cancelable) event.preventDefault();
      const multiplier = event.deltaMode === 1 ? 16 : event.deltaMode === 2 ? canvas.clientHeight : 1;
      zoom(Math.exp(clamp(-event.deltaY * multiplier * 0.0016,-0.35,0.35)));
    }, {passive:inline});
    on(canvas, "keydown", event => {
      const commands = {
        ArrowLeft: () => orbit(-18, 0), ArrowRight: () => orbit(18, 0),
        ArrowUp: () => orbit(0, 14), ArrowDown: () => orbit(0, -14),
        "+": () => zoom(1.12), "=": () => zoom(1.12), "-": () => zoom(1 / 1.12), Home: reset,
      };
      if (!Object.hasOwn(commands, event.key)) return;
      event.preventDefault();
      commands[event.key]();
    });
    on(canvas, "webglcontextlost", () => {
      failed = true;
      canvas.dispatchEvent(new CustomEvent("ruttaviewererror", { detail: new Error("Rutta 3D context lost.") }));
    });
    on(motion, "change", schedule);
    const resize = new ResizeObserver(schedule);
    resize.observe(canvas);
    canvas.style.cursor = "grab";
    // Draw once synchronously so initialization errors can reach the host.
    draw(performance.now());

    return {
      setCamera, setView, setMuted, setPowered, setActivity, setFinish, zoom, reset,
      dispose() {
        if (disposed) return;
        disposed = true;
        cancelAnimationFrame(pending);
        resize.disconnect();
        cleanups.forEach(cleanup => cleanup());
        gl.deleteBuffer(backdrop);
        parts.forEach(part => {
          gl.deleteBuffer(part.vertices);
          gl.deleteBuffer(part.indices);
        });
        gl.deleteProgram(object.program);
        gl.deleteProgram(stage.program);
        canvas.style.touchAction = previousTouch;
        canvas.style.cursor = "";
      },
    };
  }

  window.RuttaViewer = Object.freeze({ mount, finishes: finishHex });
})();
